from __future__ import absolute_import, print_function

import signal
import sys
import traceback

import Pyro4

from ta_ue_plugin_android.uepc.ssh_manager import SshManager
from ta_ue_plugin_android.uepc.ue_manager_exceptions import RunningKeywordException
from ta_ue_plugin_android.uepc.ue_pc_logger import create_ue_pc_logger
from ta_ue_plugin_android.uepc.ue_pool_controller import UePoolController

PYRO_SERVER_OBJ_NAME = "TaUeServer"
PYRO_SERVER_VERSION = 13912
IGNORE_RPC_METHODS_LOGGING = ['keep_reservation']


class TaUeServer(object):
    """
    Main pyro server object that exposes public methods to pyro client.
    Methods decorated with @Pyro4.oneway always return None. Pyro client will not wait for a response from them.
    """

    def __init__(self, host_ip, host_port, login, password, ue_pool_controller=None):
        """
        Basic initialization.
        :param ue_pool_controller:
        """
        self.host_ip = host_ip
        self.host_port = host_port
        self.logger = create_ue_pc_logger()
        self.ssh_manager = self.create_ssh_manager()
        self.register_local_ssh('127.0.0.1', login, password)
        self.ue_pool_controller = ue_pool_controller or self._new_ue_pool_controller(self.ssh_manager)
        self.daemon = None
        self.running = False

    def run_on_pool_controller(self, method_name, *args, **kwargs):
        """
        Proxying method call on ue_pool_controller.
        :param method_name:
        :param args:
        :param kwargs:
        :return:
        """
        self._log_rpc_method(method_name, "RPC method call: {}(args={}, kwargs={})".format(method_name, args, kwargs))
        try:
            returned_value = self._run_method_on_ue_pool_controller_or_ue_control(method_name, *args, **kwargs)
            self._log_rpc_method(method_name, "RPC returned value: {}".format(returned_value))
            return returned_value
        except Exception as src_exception:
            self.logger.error(src_exception, exc_info=True)
            trace = traceback.format_exc()
            to_raise = Exception("in run_on_pool_controller given method_name = {}, args= {}, "
                                 "kwargs = {}{}".format(str(method_name), str(args), str(kwargs), str(trace)))
            if isinstance(src_exception, RunningKeywordException):
                src_exception.attach_me_to_other_exception(to_raise)
            raise to_raise

    @Pyro4.oneway
    def oneway_run_on_pool_controller(self, method_name, *args, **kwargs):
        """
        Triggers method call on ue_pool_controller or ue_control and immediately sends result back to pyro client
        :param method_name:
        :param args:
        :param kwargs:
        :return:
        """
        self._log_rpc_method(method_name, "RPC method call: {}(args={}, kwargs={})".format(method_name, args, kwargs))
        try:
            returned_value = self._run_method_on_ue_pool_controller_or_ue_control(method_name, *args, **kwargs)
            self._log_rpc_method(method_name, "RPC returned value: {}".format(returned_value))
            return returned_value
        except Exception as src_exception:
            self.logger.error(src_exception, exc_info=True)
            trace = traceback.format_exc()
            to_raise = Exception("in run_on_pool_controller given method_name = {}, args= {}, "
                                 "kwargs = {}{}".format(str(method_name), str(args), str(kwargs), str(trace)))
            if isinstance(src_exception, RunningKeywordException):
                src_exception.attach_me_to_other_exception(to_raise)
            raise to_raise

    def _run_method_on_ue_pool_controller_or_ue_control(self, method_name, *args, **kwargs):
        ue_pool_controller_method = getattr(self.ue_pool_controller, method_name, None)
        if ue_pool_controller_method:
            return ue_pool_controller_method(*args, **kwargs)
        return self._run_method_on_ue_control(method_name, *args, **kwargs)

    def _run_method_on_ue_control(self, method_name, ue_sn, *args, **kwargs):
        ue_control = self.ue_pool_controller.pool.get_ue(ue_sn)
        try:
            ue_control_method = getattr(ue_control, method_name)
        except AttributeError:
            ue_control_class_name = ue_control.__class__.__name__
            raise Exception("Run method '{}' failed on {}. It's not implemented either in UePoolControler or {}\n"
                            "Available methods in UePoolController:\n{}\n"
                            "Available methods in {}:\n{}\n".format(method_name, ue_sn, ue_control_class_name, str(dir(self.ue_pool_controller)),
                                                                    ue_control_class_name, self._list_public_methods_from_object(ue_control)))
        return ue_control_method(*args, **kwargs)

    def start_pyro_daemon(self):
        """Register and start Pyro4.Daemon"""
        Pyro4.config.SOCK_REUSE = True
        Pyro4.config.REQUIRE_EXPOSE = False
        signal.signal(signal.SIGTERM, self.stop_server)
        with Pyro4.Daemon(host=self.host_ip, port=int(self.host_port)) as self.daemon:
            self.daemon.register(self, objectId=PYRO_SERVER_OBJ_NAME)
            self.running = True
            self.logger.info("Ready. Object uri")
            self.logger.info("Server Ready")
            self.logger.info("Server version: {}".format(self.get_version()))
            self.logger.info("ue_pc_pyro_server_started")
            print("ue_pc_pyro_server_started")
            try:
                self.daemon.requestLoop(loopCondition=self._still_running)
            except BaseException as e:
                self.logger("Exception in Pyro daemon requestLoop: {}".format(e.message))
                self.stop_server()
            finally:
                self.running = False

    def stop_server(self):
        """Stops pyro server => closes server program instance"""
        self.logger.debug("Stopping pyro_server")
        self.actions_before_shutdown()
        self.daemon.shutdown()

    @staticmethod
    def actions_before_shutdown():
        """Do all actions needed before killing pyro server"""
        pass

    def _still_running(self):
        return self.running

    def _log_rpc_method(self, method_name, message):
        if method_name not in IGNORE_RPC_METHODS_LOGGING:
            self.logger.debug(message)

    @staticmethod
    def get_version():
        """
        Return version.

        :return: PYRO_SERVER_VERSION
        """
        return PYRO_SERVER_VERSION

    def _new_ue_pool_controller(self, ssh_manager):
        return UePoolController(ssh_manager)

    def create_ssh_manager(self):
        """Create ssh manager for UE PC"""
        return SshManager()

    def register_local_ssh(self, hostname, username, password):
        """Add local IP to registered clients for localhost SSH operations"""
        self.ssh_manager.register(hostname, username, password)

    @staticmethod
    def _list_public_methods_from_object(object):
        return [method for method in dir(object) if
                callable(getattr(object, method)) and not method.startswith('_')]

    def close_log_handlers(self):
        """
        Manual close of log handlers in case we want to clear logs in each test in test suite.
        :return:
        """
        handlers = self.logger.handlers[:]
        for handler in handlers:
            handler.close()
            self.logger.removeHandler(handler)


if __name__ == '__main__':
    print("ue_pc_first_line")

    if len(sys.argv) == 5:
        hostIP = sys.argv[1]
        hostPort = sys.argv[2]
        login = sys.argv[3]
        password = sys.argv[4]
        print("Used given hostIP: %s, hostPort: %s" % (hostIP, hostPort))
        server = TaUeServer(hostIP, hostPort, login, password)
        server.start_pyro_daemon()
    elif len(sys.argv) == 2 and sys.argv[2] == 'version':
        print("server_version: %d" % TaUeServer.get_version())
    else:
        print("Please provide hostIP and pyroPort in argv or 'version'")
